declare module '@glimmer/runtime/lib/compiled/opcodes/vm' {
    import type { UpdatingOpcode } from "@glimmer/interfaces";
    import type { Reference } from "@glimmer/reference";
    import type { Tag } from "@glimmer/validator";
    import type { UpdatingVM } from "@glimmer/runtime/lib/vm";
    export class Assert implements UpdatingOpcode {
        private ref;
        private last;
        constructor(ref: Reference);
        evaluate(vm: UpdatingVM): void;
    }
    export class AssertFilter<T, U> implements UpdatingOpcode {
        private ref;
        private filter;
        private last;
        constructor(ref: Reference<T>, filter: (from: T) => U);
        evaluate(vm: UpdatingVM): void;
    }
    export class JumpIfNotModifiedOpcode implements UpdatingOpcode {
        private tag;
        private lastRevision;
        private target?;
        finalize(tag: Tag, target: number): void;
        evaluate(vm: UpdatingVM): void;
        didModify(tag: Tag): void;
    }
    export class BeginTrackFrameOpcode implements UpdatingOpcode {
        private debugLabel?;
        constructor(debugLabel?: string | undefined);
        evaluate(): void;
    }
    export class EndTrackFrameOpcode implements UpdatingOpcode {
        private target;
        constructor(target: JumpIfNotModifiedOpcode);
        evaluate(): void;
    }
}